//! What `CREATE TABLE ... (LIKE ... INCLUDING ALL)` doesn't copy and the swap
//! has to carry over to the new table: owner, grants (table and column),
//! row level security and policies, replica identity, publications, table
//! comment, per-column statistics targets and options. And the index and
//! constraint names: LIKE names them after the shadow table.
//!
//! The statements are generated by the server (format(), quote_ident()),
//! the same queries in the Go port.

use crate::ctx::Ctx;
use crate::sql::{quote_ident, quote_literal};
use anyhow::{bail, Result};

/// Replaced by the (renamed) column of the new table in per-column statements.
const COLUMN_PLACEHOLDER: &str = "__PGOSC_COLUMN__";

/// Table level statements, in the order they must run ('{target}' = the
/// table to apply them to, {source} = the source table). The owner goes last (ord 9): after it we
/// may no longer be the owner (still fine as superuser / member of the role).
const TABLE_PROPERTIES_SQL: &str = r#"
SELECT stmt FROM (
  SELECT 1 AS ord, format('COMMENT ON TABLE %s IS %L', '{target}', d) AS stmt
    FROM obj_description({source}::regclass, 'pg_class') d WHERE d IS NOT NULL
  UNION ALL
  SELECT 2, format('ALTER TABLE %1$s ENABLE ROW LEVEL SECURITY', '{target}')
    FROM pg_class WHERE oid = {source}::regclass AND relrowsecurity
  UNION ALL
  SELECT 2, format('ALTER TABLE %1$s FORCE ROW LEVEL SECURITY', '{target}')
    FROM pg_class WHERE oid = {source}::regclass AND relforcerowsecurity
  UNION ALL
  SELECT 3, format('CREATE POLICY %2$I ON %1$s AS %3$s FOR %4$s TO %5$s%6$s%7$s', '{target}', p.polname,
           CASE WHEN p.polpermissive THEN 'PERMISSIVE' ELSE 'RESTRICTIVE' END,
           CASE p.polcmd WHEN 'r' THEN 'SELECT' WHEN 'a' THEN 'INSERT' WHEN 'w' THEN 'UPDATE' WHEN 'd' THEN 'DELETE' ELSE 'ALL' END,
           (SELECT string_agg(CASE WHEN r = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(r)) END, ', ') FROM unnest(p.polroles) r),
           ' USING (' || pg_get_expr(p.polqual, p.polrelid) || ')',
           ' WITH CHECK (' || pg_get_expr(p.polwithcheck, p.polrelid) || ')')
    FROM pg_policy p WHERE p.polrelid = {source}::regclass
  UNION ALL
  SELECT 4, format('GRANT %2$s ON %1$s TO %3$s%4$s', '{target}', x.privilege_type,
           CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(x.grantee)) END,
           CASE WHEN x.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END)
    FROM pg_class c, aclexplode(c.relacl) x WHERE c.oid = {source}::regclass AND x.grantee <> c.relowner
  UNION ALL
  SELECT 5, format('ALTER TABLE %1$s REPLICA IDENTITY %2$s', '{target}', CASE relreplident WHEN 'f' THEN 'FULL' ELSE 'NOTHING' END)
    FROM pg_class WHERE oid = {source}::regclass AND relreplident IN ('f', 'n')
  UNION ALL
  SELECT 9, format('ALTER TABLE %1$s OWNER TO %2$I', '{target}', pg_get_userbyid(relowner))
    FROM pg_class WHERE oid = {source}::regclass
) s ORDER BY ord
"#;

/// Per column, with COLUMN_PLACEHOLDER for the column of the new table.
const COLUMN_PROPERTIES_SQL: &str = r#"
SELECT a.attname AS col, s.stmt
FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid,
LATERAL (
  SELECT format('ALTER TABLE %s ALTER COLUMN __PGOSC_COLUMN__ SET STATISTICS %s', '{target}', a.attstattarget)
    WHERE a.attstattarget IS NOT NULL AND a.attstattarget >= 0
  UNION ALL
  SELECT format('ALTER TABLE %s ALTER COLUMN __PGOSC_COLUMN__ SET (%s)', '{target}', array_to_string(a.attoptions, ', '))
    WHERE a.attoptions IS NOT NULL
  UNION ALL
  SELECT format('GRANT %s (__PGOSC_COLUMN__) ON %s TO %s%s', x.privilege_type, '{target}',
           CASE WHEN x.grantee = 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(x.grantee)) END,
           CASE WHEN x.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END)
    FROM aclexplode(a.attacl) x WHERE x.grantee <> c.relowner
) s(stmt)
WHERE a.attrelid = {source}::regclass AND a.attnum > 0 AND NOT a.attisdropped
ORDER BY a.attnum
"#;

/// Explicit publication membership (FOR ALL TABLES / TABLES IN SCHEMA cover
/// the new table by themselves). PostgreSQL 15+: column lists and row filters.
const PUBLICATIONS_SQL_15: &str = r#"
SELECT p.pubname,
       format('ALTER PUBLICATION %I ADD TABLE %s%s%s', p.pubname, '{target}',
         CASE WHEN r.prattrs IS NOT NULL THEN ' (' || (SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum)
           FROM pg_attribute a WHERE a.attrelid = r.prrelid AND a.attnum = ANY (r.prattrs)) || ')' ELSE '' END,
         CASE WHEN r.prqual IS NOT NULL THEN ' WHERE (' || pg_get_expr(r.prqual, r.prrelid) || ')' ELSE '' END) AS stmt
FROM pg_publication_rel r JOIN pg_publication p ON p.oid = r.prpubid
WHERE r.prrelid = {source}::regclass ORDER BY 1
"#;

const PUBLICATIONS_SQL: &str = r#"
SELECT p.pubname, format('ALTER PUBLICATION %I ADD TABLE %s', p.pubname, '{target}') AS stmt
FROM pg_publication_rel r JOIN pg_publication p ON p.oid = r.prpubid
WHERE r.prrelid = {source}::regclass ORDER BY 1
"#;

/// Indexes with what identifies them regardless of their name: access
/// method, uniqueness, key columns (by name, mapped through the ALTER's
/// renames by the caller), operator classes, options, expressions, predicate.
const INDEXES_SQL: &str = r#"
SELECT ic.relname AS name, c.conname, c.contype, i.indisreplident,
       (SELECT json_agg(coalesce(a.attname, '') ORDER BY k.ord)
          FROM unnest(i.indkey::int2[]) WITH ORDINALITY k(attnum, ord)
          LEFT JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum) AS cols,
       concat_ws('|', am.amname, i.indisunique, i.indisprimary, i.indnkeyatts, i.indclass::text, i.indoption::text,
                 i.indcollation::text, pg_get_expr(i.indexprs, i.indrelid), pg_get_expr(i.indpred, i.indrelid),
                 array_to_string(ic.reloptions, ',')) AS rest
FROM pg_index i
JOIN pg_class ic ON ic.oid = i.indexrelid
JOIN pg_am am ON am.oid = ic.relam
LEFT JOIN pg_constraint c ON c.conindid = i.indexrelid AND c.conrelid = i.indrelid AND c.contype IN ('p', 'u', 'x')
WHERE i.indrelid = {table}::regclass
ORDER BY i.indexrelid
"#;

#[derive(Clone, Debug)]
pub struct IndexInfo {
    pub name: String,
    pub conname: Option<String>,
    pub replident: bool,
    pub key: String,
}

/// An index of the source table and its counterpart on the shadow table.
#[derive(Clone, Debug)]
pub struct IndexPair {
    pub source: IndexInfo,
    pub shadow: IndexInfo,
}

/// Statements captured before the swap renames the tables.
#[derive(Clone, Debug, Default)]
pub struct Carry {
    /// run on the new table after the renames, owner last
    pub statements: Vec<String>,
    /// run after the renames: the old table leaves its publications
    pub old_table_statements: Vec<String>,
    /// renames giving the new table's indexes the original names, replica identity
    pub name_statements: Vec<String>,
    pub warnings: Vec<String>,
}

fn truncate_ident(s: &str, max: usize) -> &str {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

impl Ctx {
    fn source_regclass(&self) -> String {
        quote_literal(&self.qualified(&self.opts.table_name))
    }

    fn fill(&self, sql: &str, target: &str, table: Option<&str>) -> String {
        sql.replace("{source}", &self.source_regclass())
            .replace("'{target}'", &quote_literal(target))
            .replace(
                "{table}",
                &quote_literal(&self.qualified(table.unwrap_or(&self.opts.table_name))),
            )
    }

    /// The column of the new table for a column of the source table, None
    /// if the ALTER drops it.
    fn new_column_name(&self, col: &str) -> Option<String> {
        if self.dropped_columns.iter().any(|c| c == col) {
            return None;
        }
        Some(
            self.renamed_columns
                .iter()
                .find(|(old, _)| old == col)
                .map(|(_, new)| new.clone())
                .unwrap_or_else(|| col.to_string()),
        )
    }

    /// Owner, grants, RLS, policies, replica identity (FULL / NOTHING),
    /// comment, column statistics/options/grants, publications for `target`,
    /// as the source table has them right now.
    pub fn property_statements(&mut self, target: &str, reuse: bool) -> Result<Vec<String>> {
        let table_level: Vec<String> = self
            .db
            .run(&self.fill(TABLE_PROPERTIES_SQL, target, None), reuse)?
            .iter()
            .filter_map(|r| r.get("stmt").map(str::to_string))
            .collect();
        let (owner, rest): (Vec<String>, Vec<String>) = table_level
            .into_iter()
            .partition(|s| s.contains(" OWNER TO "));

        let mut out = rest;
        for row in self
            .db
            .run(&self.fill(COLUMN_PROPERTIES_SQL, target, None), reuse)?
        {
            let (Some(col), Some(stmt)) = (row.get("col"), row.get("stmt")) else {
                continue;
            };
            if let Some(new) = self.new_column_name(col) {
                out.push(stmt.replace(COLUMN_PLACEHOLDER, &quote_ident(&new)));
            }
        }
        out.extend(self.publication_statements(target, reuse)?);
        out.extend(owner);
        Ok(out)
    }

    fn publication_statements(&mut self, target: &str, reuse: bool) -> Result<Vec<String>> {
        let sql = if self.server_version >= 150000 {
            PUBLICATIONS_SQL_15
        } else {
            PUBLICATIONS_SQL
        };
        Ok(self
            .db
            .run(&self.fill(sql, target, None), reuse)?
            .iter()
            .filter_map(|r| r.get("stmt").map(str::to_string))
            .collect())
    }

    fn publication_names(&mut self, reuse: bool) -> Result<Vec<String>> {
        Ok(self
            .db
            .run(&self.fill(PUBLICATIONS_SQL, "", None), reuse)?
            .iter()
            .filter_map(|r| r.get("pubname").map(str::to_string))
            .collect())
    }

    fn indexes_of(
        &mut self,
        table: &str,
        map_columns: bool,
        reuse: bool,
    ) -> Result<Vec<IndexInfo>> {
        let rows = self
            .db
            .run(&self.fill(INDEXES_SQL, "", Some(table)), reuse)?;
        let mut out = vec![];
        for r in rows {
            let cols: Vec<String> =
                serde_json::from_str(r.get("cols").unwrap_or("[]")).unwrap_or_default();
            let cols: Vec<String> = cols
                .into_iter()
                .map(|c| {
                    if map_columns && !c.is_empty() {
                        self.new_column_name(&c)
                            .unwrap_or_else(|| format!("{c}#dropped"))
                    } else {
                        c
                    }
                })
                .collect();
            out.push(IndexInfo {
                name: r.get("name").unwrap_or_default().to_string(),
                conname: r.get("conname").map(str::to_string),
                replident: r.get("indisreplident") == Some("t"),
                key: format!(
                    "{}|{}",
                    serde_json::to_string(&cols).unwrap_or_default(),
                    r.get("rest").unwrap_or_default()
                ),
            });
        }
        Ok(out)
    }

    /// Pairs the source table's indexes with the shadow table's ones by
    /// definition. Unpaired ones keep their names (with a warning).
    pub fn index_pairs(&mut self, reuse: bool) -> Result<(Vec<IndexPair>, Vec<String>)> {
        let table = self.opts.table_name.clone();
        let shadow = self.shadow_table.clone();
        let source = self.indexes_of(&table, true, reuse)?;
        let mut candidates = self.indexes_of(&shadow, false, reuse)?;
        let mut pairs = vec![];
        let mut warnings = vec![];
        for s in source {
            match candidates.iter().position(|c| c.key == s.key) {
                Some(i) => pairs.push(IndexPair {
                    source: s,
                    shadow: candidates.remove(i),
                }),
                None => warnings.push(format!(
                    "index {} has no counterpart with the same definition on the new table, its name isn't carried over",
                    s.name
                )),
            }
        }
        Ok((pairs, warnings))
    }

    /// Everything the swap carries over, captured inside the swap
    /// transaction before the renames (the source is still `table_name`).
    pub fn capture_carry(&mut self) -> Result<Carry> {
        let t = self.opts.table_name.clone();
        let mut carry = Carry {
            statements: self.property_statements(&t, true)?,
            ..Default::default()
        };
        let old = self.qualified(&self.old_primary_table);
        for pubname in self.publication_names(true)? {
            carry.old_table_statements.push(format!(
                "ALTER PUBLICATION {} DROP TABLE {};",
                quote_ident(&pubname),
                old
            ));
        }
        let (pairs, warnings) = self.index_pairs(true)?;
        carry.warnings = warnings;
        let schema = quote_ident(&self.opts.schema);
        let mut first = vec![];
        let mut second = vec![];
        for (n, p) in pairs.iter().enumerate() {
            if p.source.name == p.shadow.name {
                continue;
            }
            // the old table's index first moves out of the way
            let tmp = format!("{}_pgosc_op_{}", truncate_ident(&p.source.name, 40), n);
            match (&p.source.conname, &p.shadow.conname) {
                (Some(scon), Some(shcon)) => {
                    first.push(format!(
                        "ALTER TABLE {old} RENAME CONSTRAINT {} TO {};",
                        quote_ident(scon),
                        quote_ident(&tmp)
                    ));
                    second.push(format!(
                        "ALTER TABLE {schema}.{t} RENAME CONSTRAINT {} TO {};",
                        quote_ident(shcon),
                        quote_ident(scon)
                    ));
                }
                _ => {
                    first.push(format!(
                        "ALTER INDEX {schema}.{} RENAME TO {};",
                        quote_ident(&p.source.name),
                        quote_ident(&tmp)
                    ));
                    second.push(format!(
                        "ALTER INDEX {schema}.{} RENAME TO {};",
                        quote_ident(&p.shadow.name),
                        quote_ident(&p.source.name)
                    ));
                }
            }
        }
        carry.name_statements = first;
        carry.name_statements.extend(second);
        if let Some(p) = pairs.iter().find(|p| p.source.replident) {
            carry.name_statements.push(format!(
                "ALTER TABLE {schema}.{t} REPLICA IDENTITY USING INDEX {};",
                quote_ident(&p.source.name)
            ));
        } else if self.replica_identity_index(true)?.is_some() {
            carry.warnings.push(
                "the replica identity index has no counterpart on the new table, replica identity stays DEFAULT".into(),
            );
        }
        Ok(carry)
    }

    fn replica_identity_index(&mut self, reuse: bool) -> Result<Option<String>> {
        let sql = format!(
            "SELECT indexrelid::regclass::text FROM pg_index WHERE indrelid = {}::regclass AND indisreplident;",
            self.source_regclass()
        );
        self.db.first_value(&sql, reuse)
    }

    /// Before the sync starts: runs the property statements against the
    /// shadow table in a transaction and rolls it back, so a missing
    /// privilege or a policy over a dropped column fails now and not at
    /// every swap attempt. Logs indexes whose names can't be carried over.
    pub fn check_carry(&mut self) -> Result<()> {
        let shadow = self.shadow_table.clone();
        let result = (|| -> Result<()> {
            for stmt in self.property_statements(&shadow, true)? {
                if let Err(e) = self.db.run(&stmt, true) {
                    bail!("The new table can't get a property of the old one ({stmt}): {e:#}");
                }
            }
            let (_, warnings) = self.index_pairs(true)?;
            for w in warnings {
                crate::warn!(w);
            }
            Ok(())
        })();
        let _ = self.db.run("ROLLBACK;", false);
        result
    }

    /// Checks done before anything is created.
    pub fn preflight(&mut self) -> Result<()> {
        let rel = self.source_regclass();
        let row = self.db.run(
            &format!(
                "SELECT c.relkind, c.relispartition, to_regclass({old}) IS NOT NULL AS old_exists,
                        pg_has_role(c.relowner, 'MEMBER') AS can_own, pg_get_userbyid(c.relowner) AS owner
                 FROM pg_class c WHERE c.oid = {rel}::regclass;",
                old = quote_literal(&self.qualified(&self.old_primary_table))
            ),
            false,
        )?;
        let Some(r) = row.first() else {
            bail!("Table {} not found", self.opts.table_name);
        };
        if r.get("relkind") == Some("p") || r.get("relispartition") == Some("t") {
            bail!("Partitioned tables and partitions are not supported (the shadow table would be a plain table)");
        }
        if r.get("old_exists") == Some("t") {
            bail!(
                "{} already exists (left by a previous run without --drop): drop or rename it first, the swap renames the table to that name",
                self.old_primary_table
            );
        }
        if r.get("can_own") != Some("t") {
            bail!(
                "The new table must get the owner of the old one ({}): run as a superuser or a member of that role",
                r.get("owner").unwrap_or_default()
            );
        }
        let sql = format!(
            "SELECT p.pubname FROM pg_publication_rel r JOIN pg_publication p ON p.oid = r.prpubid
             WHERE r.prrelid = {rel}::regclass AND NOT pg_has_role(p.pubowner, 'MEMBER');"
        );
        let foreign: Vec<String> = self
            .db
            .run(&sql, false)?
            .iter()
            .filter_map(|r| r.get("pubname").map(str::to_string))
            .collect();
        if !foreign.is_empty() {
            bail!(
                "The table is in publications {} owned by another role: run as a superuser or their owner, the new table has to join them",
                foreign.join(", ")
            );
        }
        Ok(())
    }
}
